(function(){self.onmessage=async e=>{let{id:t,blob:n}=e.data||{};try{if(!(n instanceof Blob))throw Error(`blob required`);let e=await crypto.subtle.digest(`SHA-256`,await n.arrayBuffer()),r=Array.from(new Uint8Array(e),e=>e.toString(16).padStart(2,`0`)).join(``);self.postMessage({id:t,type:`done`,hash:r})}catch(e){self.postMessage({id:t,type:`error`,message:e?.message||String(e)})}}})();